"""16 Nov 2026: Russian texts rewritten by the founders (Kosta's list), and
three photographs of the 2009 Phantom job. Russian only for the texts; the
other languages get proposals to review (content/i18n/review/2026-11-16.md)."""
import sys,json,glob
sys.path.insert(0,'tools'); import i18n
def load(f):
    t=open(f).read(); d=json.load(open(f)); assert json.dumps(d,ensure_ascii=False,indent=2)+'\n'==t,f; return d
EN=load('content/en.json'); RU=load('content/ru.json')
tabs={l:{f:load(f) for f in sorted(glob.glob(f'content/i18n/{l}*.json'))} for l in ('de','sr')}
NEW={'de':'content/i18n/de.7.json','sr':'content/i18n/sr.7.json'}
def page(d,s): return [p for p in d['pages'] if p.get('slug')==s][0]
def swap(old,new,count=1):
    global RU
    s=json.dumps(RU,ensure_ascii=False); o=json.dumps(old,ensure_ascii=False)
    assert s.count(o)==count,(old[:60],s.count(o)); RU=json.loads(s.replace(o,json.dumps(new,ensure_ascii=False)))

swap("Перегородка меняет назначение автомобиля. Но решение владельца определяет второй вопрос: что доработка отнимает.",
     "Перегородка меняет назначение автомобиля. Но владелец автомобиля хочет знать перед установкой, что именно изменится в его серийной машине.")
swap("Дизайн, инжиниринг, изготовление оснастки и производство выполняются внутри компании. Партнёру не нужно координировать нескольких подрядчиков, и ответственности некуда провалиться между ними.",
     "Дизайн, инжиниринг, изготовление оснастки и производство выполняются внутри компании. Партнёру не нужно обращаться к разным подрядчикам и координировать их работу для получения качественного продукта в запланированные сроки.")
swap("Разработка и оснастка полностью наши — включая совместные проекты, где часть панелей производит партнёр.",
     "Разработку и оснастку мы осуществим самостоятельно — в том числе и для совместных проектов, где часть работ будет производить партнёр.")
swap("Партнёр может взять ровно ту часть производства, которая ему по силам: от полного комплекта «под ключ» до одного силового каркаса с механизмами. Разработка и оснастка в любом случае остаются нашими.",
     "Партнёр может взять ровно ту часть производства, которая ему по силам: от полного комплекта «под ключ» до одного силового каркаса с механизмами. Разработка и оснастка в любом случае производятся нашими силами.")
swap("Перегородка, подогнанная по месту, существует в единственном экземпляре: следующая будет другой. Оснастка — это то, что превращает хороший результат в повторяемый.",
     "Перегородка, подогнанная по месту, существует в единственном экземпляре: следующая будет другой. Оснастка — это то, что позволяет повторять один и тот же результат сколь угодно долго.")
swap("Для партнёра это две вещи, которые прямо попадают в его калькуляцию: время монтажа можно планировать, а переделок нет.",
     "Это принципиально важные моменты для партнёра, влияющие на экономику проекта: можно планировать время монтажа, нет непредвиденных переделок и простоев.")
swap("Восемь моделей доведены до производственной оснастки. Тираж по ним масштабируется без новых вложений в разработку.",
     "Восемь моделей доведены до производственной оснастки. Их производство масштабируется в любой момент без новых вложений в разработку.")
swap("Новое поколение готово в 2026 · 14 комплектов 2015–2019","В 2026 году разработано новое поколение · 14 комплектов 2015–2019")
swap("Новое поколение, готово в 2026","В 2026 году разработано новое поколение")
swap("Все проекты с 2007 года, включая ранние единичные работы и серию VW Multivan, перечислены на странице доступности — с годами, тиражами и характером каждого проекта.",
     "Все проекты с 2007 года, включая ранние единичные работы и серию VW Multivan, перечислены на странице доступности — с годами, тиражами и сложностью каждого проекта.")
swap("Три состояния, и разница между ними — в том, сколько партнёру нужно вложить до прихода первого комплекта.",
     "Три фазы готовности, разница между ними — в степени готовности продукта.")
swap("Цена — функция годового тиража, поэтому мы считаем под модель, рынок и план поставок, а не публикуем прайс-лист.",
     "Стоимость рассчитывается исходя из технологической готовности и потенциального объёма производства, так что расчёты по новым разработкам всегда индивидуальны, а прайс-листы есть только у серийной продукции, находящейся в производстве.")
swap("Партнёр получает комплект, готовый к монтажу. Всё до этой точки — наше, всё начиная с обтяжки — партнёра. Линия проходит в одном и том же месте на каждом проекте.",
     "Партнёр получает комплект, готовый к монтажу. Ему остаётся выполнить обтяжку и произвести установку перегородки. По запросу партнёра мы готовы обсудить иные варианты и найти совместные решения.")
swap("Какой партнёр нужен под каждый класс","Возможные категории партнёрства")

# 11. range page: the footnote becomes a callout in large type, with a direct contact
r=page(RU,'range'); lu=[b for b in r['blocks'] if b['type']=='lineup'][0]
assert lu.pop('footnote').startswith("Дополнительно к перегородкам")
r['blocks'].insert(r['blocks'].index(lu)+1,{
 "type":"note","title":"Полный цикл разработки салона",
 "body":["Помимо перегородок мы разрабатываем и производим задний узел — каркас-подиум с консолью-подлокотником для установки опционального заднего дивана — и любые внутренние панели салона по индивидуальному дизайну.",
         "По запросу партнёров мы берём на себя полный цикл разработки любых элементов салона — вплоть до создания полностью собственного салона автомобиля.",
         "По вопросам сотрудничества и расширения бизнеса обращайтесь напрямую к Константину Штейну."],
 "action":{"label":"Написать Константину Штейну","href":"/ru/partners/#enquiry"}})

# 15. partners page: price block
p=page(RU,'partners'); b=[b for b in p['blocks'] if b.get('title')=="Как формируется цена"]; assert len(b)==1; b=b[0]
b['title']="Почему мы не публикуем прайс-листов?"
b['body']=["На стоимость готового изделия влияют: наличие технологической базы, готовность оснастки и главное — планирование объёмов производства. Стоимость перегородки всегда оговаривается с партнёром заранее. При увеличении партии возможно её снижение, при уменьшении количества заказов она также пересматривается.",
 "Поставка идёт по плану, в который можно вносить коррективы, но — заблаговременно. Производственный цикл комплекта — четыре месяца, но при согласованном объёме поставок и своевременной предоплате изделие отгружается со склада в прогнозируемый срок.",
 "Для рынков ЕС, США и Канады мы поставляем перегородки из Сербии — страны-кандидата в ЕС (сербские промышленные товары с 2000 года ввозятся в Союз без таможенной пошлины; позже этот режим закреплён в Соглашении о стабилизации и ассоциации). Для партнёра в ЕС это значит отсутствие пошлины на комплект — остаются только импортный НДС и обычное таможенное оформление. За пределами ЕС действует тариф страны ввоза. Для иных стран возможна поставка с нашего производства в России — конкретную схему мы определим с вами в процессе переговоров.",
 "Назовите модель, рынок и планируемое количество — пришлём ориентиры по стоимости, комплектность поставки и план отгрузок."]

# photographs: 2009 Phantom job, all languages
NEWIMG={'ru':[("founder/phantom/05.jpg","Илья Большаков за работой в заднем салоне Rolls-Royce Phantom","Подгонка отделки по месту"),
              ("founder/phantom/06.jpg","За работой в заднем салоне Phantom","Доводка панелей в салоне"),
              ("founder/phantom/07.jpg","Rolls-Royce Phantom в сервисном центре","Phantom в сервисном центре Rolls-Royce")],
        'en':[("founder/phantom/05.jpg","Ilya Bolshakov at work in the rear compartment of a Rolls-Royce Phantom","Fitting the trim in place"),
              ("founder/phantom/06.jpg","At work in the rear compartment of the Phantom","Finishing the panels in the car"),
              ("founder/phantom/07.jpg","Rolls-Royce Phantoms in a service centre","Phantoms in a Rolls-Royce service centre")]}
TR={"Ilya Bolshakov at work in the rear compartment of a Rolls-Royce Phantom":("Ilya Bolshakov bei der Arbeit im Fond eines Rolls-Royce Phantom","Ilya Bolshakov na poslu u zadnjem delu kabine Rolls-Royce Phantoma"),
    "Fitting the trim in place":("Anpassen der Verkleidung vor Ort","Prilagođavanje obloga na licu mesta"),
    "At work in the rear compartment of the Phantom":("Bei der Arbeit im Fond des Phantom","Na poslu u zadnjem delu kabine Phantoma"),
    "Finishing the panels in the car":("Feinarbeit an den Paneelen im Fahrzeug","Dorada panela u vozilu"),
    "Rolls-Royce Phantoms in a service centre":("Rolls-Royce Phantom in einem Servicezentrum","Rolls-Royce Phantom vozila u servisnom centru"),
    "Phantoms in a Rolls-Royce service centre":("Phantom in einem Rolls-Royce-Servicezentrum","Phantom u servisnom centru Rolls-Royce")}
for lang,d in (('ru',RU),('en',EN)):
    fp=page(d,'founders')
    e=[e for b in fp['blocks'] for e in (b.get('entries') or []) if any(i['src']=='founder/phantom/01.jpg' for i in e.get('images',[]))]
    assert len(e)==1; e=e[0]
    assert not any(i['src']=='founder/phantom/05.jpg' for i in e['images'])
    e['images']+= [{"src":s,"alt":a,"caption":c} for s,a,c in NEWIMG[lang]]
for en,(de,sr) in TR.items():
    tabs['de'][NEW['de']][i18n.key(en)]=de; tabs['sr'][NEW['sr']][i18n.key(en)]=sr
for f,d in (('content/en.json',EN),('content/ru.json',RU)): open(f,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
for l in tabs:
    for f,d in tabs[l].items(): open(f,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('ok')
